interface Shape {                        // no backing fields allowed here
    val area: Double                     // abstract property
    fun describe(): String = "area=$area" // default implementation
}

class Square(private val side: Double) : Shape {
    override val area get() = side * side // state lives in the class
}

fun render(s: Shape) = println(s.describe())

