fun interface Predicate { fun accept(i: Int): Boolean }  // one abstract member

fun countIf(xs: List<Int>, p: Predicate): Int = xs.count { p.accept(it) }

val isEven = Predicate { it % 2 == 0 }   // SAM conversion from a lambda
